BEGIN;
-- PT112-S4-Q8
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND q.stimulus=$batch01$Archaeologist: The fact that the ancient Egyptians and the Maya both built pyramids is often taken as evidence of a historical link between Old-and New-World civilizations that is earlier than any yet documented. But while these buildings are similar to each other, there are important differences in both design and function. The Egyptian pyramids were exclusively tombs for rulers, whereas the Mayan pyramids were used as temples. This shows conclusively that there was no such link between Old-and New-World civilizations.$batch01$ AND q.prompt=$batch01$Which one of the following most accurately describes a flaw in the archaeologist's argument?$batch01$ AND q.correct_choice=$batch01$E$batch01$) THEN RAISE EXCEPTION 'Question changed: PT112-S4-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S4-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$The argument equivocates with respect to the term “evidence. ”$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S4-Q8 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$The argument appeals to emotion rather than to reason.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S4-Q8 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$The argument assumes the conclusion it is trying to prove.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S4-Q8 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$The argument incorrectly relies on words whose meanings are vague or imprecise.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S4-Q8 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$The argument presumes that no other evidence is relevant to the issue at hand.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT112-S4-Q8 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT112-S4-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$There was *no* early historical link between Old- and New-World civilizations.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Egyptian and Mayan pyramids differ in design and function; Egyptian ones were tombs, Mayan ones temples.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Those differences may weaken one proposed piece of evidence for a link. But proving that these particular buildings were used differently would not settle whether some other evidence establishes contact. Nor does a historical link require identical building designs or uses. The conclusion "no such link" reaches well past the evidence about pyramids.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for the move from challenging one line of evidence to treating the whole historical question as settled.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$"Evidence" is used consistently as support for a historical link. The archaeologist disputes how strong the pyramid comparison is; no second meaning of the word drives the inference.$batch01$), ($batch01$B$batch01$, $batch01$The argument cites design and function, not an emotional reaction intended to replace evidence.$batch01$), ($batch01$C$batch01$, $batch01$The premise is about differences between pyramids; it does not simply restate the claim that there was no historical link.$batch01$), ($batch01$D$batch01$, $batch01$The terms are sufficiently clear for the argument's purpose. The problem remains even if every feature and use is defined precisely.$batch01$), ($batch01$E$batch01$, $batch01$Differences between the pyramids at most challenge one proposed indication of contact. The categorical conclusion assumes there is no other relevant evidence of an early link. That assumption is unsupported.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT112-S4-Q8$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
